  "religion.preamble.headlineGrad": "犬を信じて",
  "religion.preamble.headlineLine": "疑わない",
  "religion.preamble.text": "私たち、犬好きの国民は — 地球上のすべての犬の<strong>無限の忠誠心</strong>、<strong>真の愛</strong>、そして<strong>純粋な魂</strong>を知り — 人間社会における犬の地位を高め、<strong>コミュニティ</strong>を築き、彼らの生活を<strong>より良く</strong>し、困っているすべての犬の運命を<strong>書き換えるために</strong>、この憲法を制定する。",
