  "wall.hero.total": "1,000,000",
  "wall.hero.dogs": "犬",
  "wall.hektor.msg": "Hekthor、君は僕の最大の英雄であり、最高の親友であり、忠実な相棒であり、容赦のない師だ——君は僕の人生で最も美しい物語だ。君のおかげで僕は犬の宗教を立ち上げ、そして僕の愛は少しも特別なんかじゃないと気づいた——かつて犬を愛したことのある人は誰もが、心の中でまったく同じものを感じているんだ。最高の人生を一緒に過ごしてくれてありがとう。愛してるよ。",
  "wall.info.title": "1,000,000匹の犬。<br/>達成できるか？",
  "wall.info.body": "DOGYPTは犬好きのためのムーブメントです。すべての犬にユニークなHeroglyph — グローバルPackの永続的な場所。私たちは百万人のヒーローを集めています。最初の一人になってください。",
