  "whatNext.s1.title": "最初の一歩",
  "whatNext.s1.hook": "人間にとっての小さな一歩 — 犬族にとっての偉大な飛躍。",
  "whatNext.s1.body": "あなたのHeroglyphは、世界中で犬を称えるムーブメントの一員であることを宣言しました。<b>最初の一歩は踏み出された。</b>",
  "whatNext.s2.title": "あなたは今、Dogyptianだ",
