  "whatNext.s2.body": "WALLに永遠に刻まれた。私たちひとりひとりが少しを贈る — そして<b>ともに、犬たちに十分を与える。</b>",
  "whatNext.s3.title": "変化の一部になろう",
  "whatNext.s3.hook": "一つの肉球は足跡を残す。百万の肉球は道を作る。",
  "whatNext.s3.body": "百万のHeroglyphへ到達する力を貸してほしい — 友達を誘おう。<b>Heroglyphが増えるほど = すべての犬にとっての善も増える。</b>",
