  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. 群れの内側：他のメンバーに見えるもの",
  "privacy.s12.body": "第3条では公開のGodsGridについて説明しています。群れの内側 — メンバー専用エリア — では、ログインしている他のメンバーにはさらに多くが見えます：あなたの名前、ドギプト番号、愛犬の名前と写真、あなたが入力した愛犬の属性、記録または告知した外出、あなたの評価やコメント、そしてプロフィールに書いた内容すべてです。メールアドレス、郵送先住所、支払い情報、他の人とのメッセージは見えません。外出を公開として告知すると、トレイル、日付、愛犬が全メンバーに表示され、参加を申し込めるようになります — それが告知の意味です。非公開にした外出は、あなたと既に参加する人だけに見えます。どちらにするかはあなた次第で、いつでも変更できます。",
  "privacy.s13.title": "13. メッセージと報告",
  "privacy.s13.body": "メンバー間の個人メッセージは、セッションをまたいで会話が残るよう私たちのデータベース（Supabase）に保存されます。法的根拠：GDPR第6条第1項(b) — これはあなたが支払った会員資格の一部です。私たちは通常これを読まず、広告やプロファイリングに使うこともありません。会話を開くのは、報告されたとき、具体的な悪用やセキュリティ事案を調査するとき、または法律で求められるときだけです。報告には、あなたが選んだ理由、任意のメモ、そして報告対象への参照が保存されます — 別のコピーは保存されません。ブロックはメンバーIDのペアとして保存されます。アカウントを削除すると、あなたのメッセージも一緒に削除されます。相手のスレッドに残るコピーは、削除されたメンバーからのものとして表示されます。その会話は相手のものでもあるからです。",
  "terms.s12.title": "12. 投稿するコンテンツ",
  "terms.s12.body": "HEROGLYPHとともに、群れの中でコンテンツを投稿できます：外出の写真、ルートや場所、外出の説明、評価、コメントや質問、そしてプロフィールに書く内容すべてです。外出を「歩いた」と記録すると、他のメンバーにはあなたの名前と一緒に歩いた犬が見えます。投稿したものの所有権はあなたに残ります。投稿することで、あなたはDOGYPT s.r.o.に対し、サービスの運営と宣伝のために、そのコンテンツを保存・表示・加工するための、全世界的・無償・非独占的なライセンスを付与します — 例えば、外出の写真を地図上や外出一覧、シェアカードに表示するためです。このライセンスはコンテンツがサービス上にある間続きます。コンテンツやアカウントを削除すればライセンスは終了しますが、バックアップは通常の周期で期限切れになるまで残ります。私たちはあなたのコンテンツを販売せず、他人の自己利用のためにライセンスを与えることもありません。投稿する権利があるものだけを投稿してください — 他人が撮った写真や、写真に写っている識別可能な人物も含みます。",
  "terms.s13.title": "13. メンバー間のメッセージ",
  "terms.s13.body": "メンバーは直接メッセージを送り合えます。メッセージは参加者間で非公開です — 私たちは通常これを読まず、広告に使うこともありません。再びアクセスしたときに会話が残るようサーバーに保存され、次の3つの場合に会話を読むことがあります：誰かが報告したとき、具体的な悪用やセキュリティ事案を調査するとき、法律で求められるときです。他のメンバーはいつでもブロックできます。ブロックは即時に双方向で有効になります。メッセージはオンラインの会話と同じように扱ってください — 支払い情報、パスワード、保存されたくない文書は送らないでください。",
  "terms.s14.title": "14. 報告とモデレーション",
  "terms.s14.body": "プロフィール、外出、会話は報告できます。報告は私たちに届き、人間が読みます — 現在は創設者のMatej Stachoです。すべての報告を7日以内に確認することを目指しています。発見した内容に応じて、何もしない、コンテンツを削除する、メンバーに警告する、投稿できる内容を制限する、またはアカウントを閉鎖することがあります。あなたのコンテンツに対応した場合、理由をメールでお知らせし、返信して異議を申し立てることができます。第7条に違反する場合は、こちらの判断でコンテンツを削除することもあります。意図的または繰り返しの悪用 — ハラスメント、スパム、偽の外出、未成年に関わるコンテンツ — は、追加の警告なくアカウントを終了させます。",
