  "pack.cal.life.tgtBody": "ホリスティックなケアが加えられる、最大5年の余命 — 体型を保つこと、野外での運動、歯、睡眠、そして不必要な薬をできるだけ減らすこと。",
  "pack.cal.life.tgtSrc": "おおよその推定であり、約束ではありません。測定されているのはそのうち一つだけです：体型を保つことだけでラブラドールの寿命が1.8年延びました（Purina Life Span Study、JAVMA 2002）。",
  "pack.cal.life.intro": "以下は、愛犬の生涯全体をブロックで表したものです。1ブロック＝1週間、1行＝1年。一方では少し怖く感じるかもしれませんが、もう一方ではまさに「すべての瞬間を大切にし、後回しにしない」ための気づきです。",
