  "pack.cal.life.recSince": "{year}年から",
  "pack.cal.life.tip.weight.title": "体型を保つことだけが証明されている",
  "pack.cal.life.tip.weight.body": "犬のためにできることの中で、寿命について最も確かな証拠があるのはひとつ：体重を増やさせないことです。スリムな犬と少し太った犬の差は年単位で、月単位ではありません。押さなくても肋骨が触れるくらいが目安です。",
  "pack.cal.life.tip.move.title": "ブロックの周りを一周するのではなく、本物の地形での運動",
  "pack.cal.life.tip.move.body": "不整地は関節、筋肉、そして頭を活発に保ちます。あなたが記録する外出のひとつひとつが、このグリッド上で濃い色の週になります — そして濃い週の数こそ、あなたが実際に影響を与えられるものです。",
  "pack.cal.life.tip.food.title": "犬が食べ物だと分かる食べ物",
  "pack.cal.life.tip.food.body": "原材料とボウルの間のステップが少ないほど、途中で何かがおかしくなる可能性も減ります。カリカリ（ドライフード）は罪ではありませんが、食事そのものでもありません — ショートカットです。",
  "pack.cal.life.tip.chem.title": "本当に必要なときだけ薬を使う",
  "pack.cal.life.tip.chem.body": "年間通しての寄生虫対策、便宜のための麻酔、「念のため」の抗生物質は、ルーティンではなく判断です。ひとつひとつについて自分に問いましょう：やらなかったらどうなる？答えが「何も起きない」なら、やらないでください。",
  "pack.cal.life.tip.stress.title": "休息も運動と同じくらい大切",
  "pack.cal.life.tip.stress.body": "常に警戒している犬は、体を内側から消耗させます。邪魔されない睡眠、予測できる日常、運動後の静けさは怠惰ではありません — それは体が自分を修復している時間です。",
  "pack.cal.life.tip.protocol.title": "パニックで動物病院に駆け込む代わりにプロトコルを",
  "pack.cal.life.tip.protocol.body": "駆虫、糞便検査、血液検査にはカレンダー上にそれぞれの期間があります。年に2回血液を調べる犬は、治療されているのではなく — 先回りされているのです。",
  "pack.cal.life.tip.joints.title": "関節は痛み出す前に対処する",
  "pack.cal.life.tip.joints.body": "あなたの犬はシニア期に入っています。関節ケアの期間はカレンダー上で11月から始まります — 足を引いているからではなく、そうならないためです。",
