  "pack.hero.popLevel1": "献身のレベルは、犬という種のために積んだ善行 — 散歩、ケア、困っている犬に差し出した手 — によって上がります。",
  "pack.hero.popLevel2": "ランクは全員共通の22段階で、お金で買うことはできません。カウントはDOGYPTがモバイルアプリに移行したときから始まります。",
