  "pack.hero.popBonesEyebrow": "通貨",
  "pack.hero.popBones1": "BONESはDOGYPTの通貨です。今は誰かを招待することで獲得できます — 友達1人につき+20🦴、その友達がさらに誰かを招待すると、さらに+10🦴。このピルで確認できます。",
