  "pack.hero.popDevotion1": "献身（☥）は、あなたが実際に愛犬へ与えているもの — 一緒にいる時間、散歩、日々の習慣 — を測ります。",
  "pack.hero.popDevotion2": "アプリを毎日手にするようになったら集められるようになります。それまでは、何も測っていない計測器になってしまいます。",
