  "pack.network.ads.body": "有料広告は新しい犬好きを見つけるにはとても効率が悪い方法です — そして私たちのお金を大企業に投げ込むようなものです。活動している運動のメンバーに直接報酬を与えるほうがはるかに効果的です。ただひとつ注意点があります：<strong style=\"font-weight:600\">本当に効果があるのは、あなたが実際に外に出て、周りの人に私たちのことを話してくれた場合だけです</strong> :)",
