  "pack.network.inLine": "あなたの系譜の中で",
  "pack.network.info.bones.body": "BONESはDOGYPTの内部通貨 — 実在するもののための遊び心ある名前です。犬は骨で支払い、私たちもそうします。犬好きを群れに招き、運動を前進させることで<b>獲得</b>し、DOGYPTの中で<b>使う</b>ことができます：シェルターの募金を支援したり、グッズを手に入れたり、後には他のドギプト人に彼らの作ったものへの支払いをしたりすることで。<b>{n} BONES = 1€。</b>",
  "pack.network.info.bones.cap": "BONESとは？",
  "pack.network.info.why.body": "この規模の運動はお金で買えません — どんな予算も、一人のドギプト人が友人に届くようには知らない人に届きません。だから群れは、届く力がある場所 — あなたのところ — に報酬を置きます。誰かがあなたのリンクから参加すると<b>{l1} BONES</b>を獲得します。その人がさらに誰かを連れてくると、さらに<b>{l2}</b>獲得します。言葉を広めるすべてのドギプト人はセールスマンではなく — 伝道者であり、私たちはその仕事を尊重します。",
  "pack.network.info.why.cap": "あなたにお願いする理由",
  "pack.network.intro": "運動が成長するのは、メンバーがメッセージを広め、新しい人を連れてくるときだけです。だからあなたに直接お願いします：<strong style=\"color:#2a1608;font-weight:600\">知っている犬好きを招待してください</strong>。仕組みは正確に以下の通りです。",
